_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:repository.nie.edu.sg:10497/32227", "doi": null, "is_oa": true, "landing_page_url": "https://educationaldatamining.org/edm2026/proceedings/2026.EDM.short-papers.34/index.html", "pdf_url": "https://educationaldatamining.org/edm2026/proceedings/2026.EDM.short-papers.34/2026.EDM.short-papers.34.pdf", "source": {"id": "https://openalex.org/S7407063280", "display_name": "NIE Digital Repository (National Institute of Education, Nanyang Technological University)", "issn_l": null, "issn": null, "is_oa": false, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": null, "host_organization_name": null, "host_organization_lineage": [], "host_organization_lineage_names": [], "type": "repository"}, "license": "cc-by-nc-nd", "license_id": "https://openalex.org/licenses/cc-by-nc-nd", "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "Conference Paper"}, "abstract": "Curiosity is central to learning and human development, yet it is typically studied as an individual psychological state. Using a social cognitive lens, this study examines whether and how curious behaviors are transmitted socially in student-led online discussions. We first constructed and validated a new large-scale dataset from a student-driven educational forum on Reddit (full dataset: \\textasciitilde 55,000 users, \\textasciitilde 39,000 posts; \\textasciitilde 667,000 comments). Curiosity was operationalized as question-posing using a 2×2 question type taxonomy involving open/closed and possibility thinking dimensions. Generalized linear models revealed clear social transmission effects: question-posing in comments generally increased questioning in subsequent replies, regardless of question type. Parallel mediation analyses involving two categories of discussion features - cognitive and socio-affective - uncovered pathways of transmission of curiosity involving social endorsement, cognitive alignment, and selective mimicry. These findings advance the field by demonstrating that curiosity is socially transmitted, highlighting its contingent spread, and providing insights into how educators and platform developers can intervene and design features to steer discussion trajectories. Our research further contributes descriptively via a new taxonomy of question-posing and the dissemination of a new online discus-sion corpus useful for future research."}]", "excerpt_truncated": true, "source_sha256": "9f5231710df018376e8d80b45e11ebaef3b849a214c24ba96e000fae88fbfea0", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1109/access.2021.3140175", "openalex:W4206484811"], "source_candidates": ["https://doi.org/10.1109/access.2021.3140175", "https://ieeexplore.ieee.org/ielx7/6287639/9668973/09667507.pdf"], "source_candidate_identities": {}}
